package com.bananalab.lite;
import android.content.*;
import org.json.*;import java.io.*;import java.util.*;
/** The reader examines itself on the device: questions built from saved text, graded against the literal sentence.
 *  «apartado» blocks were never trained; «estudiado» blocks were. A worse successor is replaced by the best checkpoint. */
final class LectorExam{
 static final int ITEMS=12,EVERY=10,HISTORY=30,REVIEW=40;
 static final class Item{final String fragment,question,sentence,id,sha;final int ordinal;final boolean held,correction;Item(String f,String q,String s,NotebookDisk.Hit h,boolean x){fragment=f;question=q;sentence=s;id=h.doc.id;sha=h.doc.sha;ordinal=h.ordinal;held=x;correction=h.doc.title.equals("Corrección del usuario");}}
 static final class Score{int total,right,heldTotal,heldRight,fixedTotal,fixedRight;double loss;final List<Item> failed=new ArrayList<>();
  /** Whether this model reads clearly worse than the other on the same items. */
  boolean worseThan(Score o){return right+1<o.right||right<=o.right&&loss>o.loss+.15;}
  JSONObject json(BananaTransformer m)throws Exception{return new JSONObject().put("time",System.currentTimeMillis()).put("items",total).put("right",right).put("heldItems",heldTotal).put("heldRight",heldRight).put("fixedItems",fixedTotal).put("fixedRight",fixedRight).put("loss",loss).put("parameters",m.parameters()).put("layers",m.layers);}}
 /** Up to `limit` questions: the user's corrections first, then set-aside blocks, then studied blocks, rotating with `round`. */
 static List<Item> items(BananaTransformer m,NotebookDisk disk,JSONObject state,int limit,int round)throws Exception{List<Item> fixed=new ArrayList<>(),held=new ArrayList<>(),studied=new ArrayList<>();JSONObject cursors=state.getJSONObject("cursors");
  for(NotebookDisk.Doc d:LectorTraining.ordered(disk)){JSONObject cur=cursors.optJSONObject(d.id);int reached=cur!=null&&cur.optString("sha").equals(d.sha)?(cur.optBoolean("done")?Integer.MAX_VALUE:cur.optInt("ordinal")):0;boolean correction=d.title.equals("Corrección del usuario");
   if(!correction&&held.size()>=limit*3&&studied.size()>=limit*3)break;for(int ordinal=0;ordinal<400;ordinal++){if(correction?fixed.size()>=4:held.size()>=limit*3&&studied.size()>=limit*3)break;boolean reserved=LectorTraining.reserved(ordinal);if(!reserved&&ordinal>=reached&&!correction)break;List<NotebookDisk.Hit> hits=disk.index.slice(d.id,ordinal,1);if(hits.isEmpty())break;NotebookDisk.Hit hit=hits.get(0);if(hit.ordinal!=ordinal){ordinal=hit.ordinal;reserved=LectorTraining.reserved(ordinal);if(!reserved&&ordinal>=reached&&!correction)break;}
    List<String> windows=Lector.windows(m,hit.text,new HashSet<String>(),1);if(windows.isEmpty())continue;LectorTraining.Batch b=LectorTraining.batch(m,hit.doc.title,windows.get(0),null);if(b.probes.isEmpty())continue;String[] p=b.probes.get((round+ordinal)%b.probes.size());Item item=new Item(p[0],p[1],p[2],hit,reserved&&!correction);List<Item> target=correction?fixed:reserved?held:studied;if(target.size()<limit*3)target.add(item);}}
  List<Item> out=new ArrayList<>();for(int i=0;i<fixed.size()&&out.size()<4;i++)out.add(fixed.get(i));int half=(limit-out.size()+1)/2;pick(out,held,Math.min(half,held.size()),round);pick(out,studied,limit-out.size(),round);pick(out,held,limit-out.size(),round+half);return out;}
 static void pick(List<Item> out,List<Item> from,int count,int round){for(int i=0;i<count&&!from.isEmpty();i++){Item item=from.get((round*7+i*Math.max(1,from.size()/Math.max(1,count)))%from.size());if(!out.contains(item))out.add(item);}}
 static Score grade(BananaTransformer m,List<Item> items,ReadingWeights.Governor governor)throws Exception{Score s=new Score();List<TransformerTraining.Sequence> rows=new ArrayList<>();for(Item item:items){if(governor!=null)governor.check();String found=Lector.ground(item.fragment,Lector.generate(m,item.fragment,item.question));boolean ok=found!=null&&new Lector.Flat(found,true).text.toString().equals(new Lector.Flat(item.sentence,true).text.toString());s.total++;if(ok)s.right++;else s.failed.add(item);if(item.held){s.heldTotal++;if(ok)s.heldRight++;}if(item.correction){s.fixedTotal++;if(ok)s.fixedRight++;}TransformerTraining.Sequence q=LectorTraining.grounded(m,item.fragment,item.question,item.sentence);if(q!=null)rows.add(q);}s.loss=rows.isEmpty()?0:LectorTraining.loss(m,rows,governor);return s;}
 /** Records the exam, queues failed studied blocks for review and decides whether the best previous checkpoint must return. */
 static boolean record(JSONObject state,BananaTransformer m,Score current,Score best)throws Exception{JSONArray old=state.optJSONArray("exams"),next=new JSONArray();if(old!=null)for(int i=Math.max(0,old.length()-HISTORY+1);i<old.length();i++)next.put(old.getJSONObject(i));boolean rollback=best!=null&&current.worseThan(best);JSONObject row=current.json(m);if(best!=null)row.put("bestRight",best.right).put("bestLoss",best.loss).put("rolledBack",rollback);next.put(row);state.put("exams",next).put("sinceExam",0).put("examRound",state.optInt("examRound")+1);
  JSONArray review=state.optJSONArray("review");if(review==null)review=new JSONArray();Set<String> queued=new HashSet<>();for(int i=0;i<review.length();i++)queued.add(review.getJSONObject(i).getString("id")+":"+review.getJSONObject(i).getInt("ordinal"));for(Item item:current.failed)if(!item.held&&review.length()<REVIEW&&queued.add(item.id+":"+item.ordinal))review.put(new JSONObject().put("id",item.id).put("sha",item.sha).put("ordinal",item.ordinal));state.put("review",review);return rollback;}
 static boolean charging(Context c){try{Intent b=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));return b!=null&&b.getIntExtra("plugged",0)!=0;}catch(Exception e){return false;}}
 static boolean due(Context c,JSONObject state){return state.optInt("sinceExam")>=EVERY;}
 static BananaTransformer champion(Context c,JSONObject state)throws Exception{JSONObject row=state.optJSONObject("champion");if(row!=null){File f=new File(row.getString("path"));if(f.isFile()&&ProjectRuntime.digest(f).equals(row.getString("sha256")))try(InputStream in=new FileInputStream(f)){return BananaTransformer.container(in);}}try(InputStream in=c.getAssets().open(ModelDepot.READER)){return BananaTransformer.container(in);}}
 /** Exam of the active reader against the best checkpoint on the same questions. Caller holds no lock requirement beyond TRAIN. */
 static String run(Context c,boolean background)throws Exception{NotebookDisk disk=NotebookDisk.of(c);JSONObject state=LectorTraining.state(c);BananaTransformer m=Lector.copy(c);ReadingBudget governor=new ReadingBudget(c,420,background);List<Item> items=items(m,disk,state,ITEMS,state.optInt("examRound"));if(items.isEmpty()){state.put("sinceExam",0);LectorTraining.save(c,state);return "Todavía no puedo armar un examen: hacen falta lecturas guardadas con oraciones de las que sacar preguntas.";}
  Score current=grade(m,items,governor),best=null;String active=ModelDepot.active(c,"reader")?ModelDepot.row(c,"reader").getString("sha256"):"base",champion=state.optJSONObject("champion")==null?"base":state.getJSONObject("champion").getString("sha256");if(!active.equals(champion))best=grade(champion(c,state),items,governor);
  boolean rollback=record(state,m,current,best);String verdict;
  if(rollback){String revision=ModelDepot.revision(c,"reader");JSONObject row=state.optJSONObject("champion");if(row==null){SharedPreferences.Editor e=ModelDepot.prefs(c).edit().remove("reader").remove("readerBackup");if(!e.commit())throw new IOException("No pude volver al lector base");}else ModelDepot.publish(c,"reader",new File(row.getString("path")),new JSONObject().put("kind","reader").put("accepted",true).put("rollback",true),revision);Lector.forget();verdict="El lector nuevo leyó peor que el mejor anterior en las mismas preguntas ("+current.right+" contra "+best.right+"): volví al anterior.";}
  else{if(ModelDepot.active(c,"reader"))state.put("champion",new JSONObject().put("path",ModelDepot.row(c,"reader").getString("path")).put("sha256",ModelDepot.row(c,"reader").getString("sha256")));else state.remove("champion");verdict=best==null?"Es el mismo modelo que ya estaba como mejor.":"El lector actual no leyó peor que el mejor anterior ("+current.right+" contra "+best.right+"): queda como mejor.";}
  LectorTraining.save(c,state);LectorTraining.prune(c);return "Examen propio: "+current.right+" de "+current.total+" oraciones exactas"+(current.heldTotal>0?" · en bloques apartados que nunca entrenó: "+current.heldRight+" de "+current.heldTotal:" · todavía sin bloques apartados (hacen falta documentos de cinco bloques o más)")+(current.fixedTotal>0?" · en tus correcciones: "+current.fixedRight+" de "+current.fixedTotal:"")+".\n"+verdict+(current.failed.isEmpty()?"":"\nVoy a repasar "+Math.min(current.failed.size(),REVIEW)+" bloques estudiados donde falló.")+"\nLas preguntas salen de plantillas sobre tus propias lecturas; no es un examen externo.";}
 static boolean background(Context c)throws Exception{run(c,true);return true;}
 static String now(Context c)throws Exception{if(!LectorTraining.TRAIN.tryLock())return "El lector está entrenando ahora; probá de nuevo en un momento.";try{return run(c,false);}finally{LectorTraining.TRAIN.unlock();}}
 static String history(JSONObject state)throws Exception{JSONArray exams=state.optJSONArray("exams");if(exams==null||exams.length()==0)return "\nExámenes propios: todavía ninguno (se toma uno cada "+EVERY+" bloques entrenados, o decí «tomate un examen»).";StringBuilder out=new StringBuilder("\nExámenes propios (del más viejo al más nuevo): ");java.text.SimpleDateFormat day=new java.text.SimpleDateFormat("dd/MM",Locale.ROOT);for(int i=Math.max(0,exams.length()-8);i<exams.length();i++){JSONObject e=exams.getJSONObject(i);out.append(i>Math.max(0,exams.length()-8)?" · ":"").append(day.format(new Date(e.getLong("time")))).append(' ').append(e.getInt("right")).append('/').append(e.getInt("items"));if(e.optBoolean("rolledBack"))out.append(" (volví al anterior)");}if(exams.length()>=6){double recent=0,earlier=0;for(int i=exams.length()-3;i<exams.length();i++)recent+=exams.getJSONObject(i).getInt("right")/(double)Math.max(1,exams.getJSONObject(i).getInt("items"));for(int i=exams.length()-6;i<exams.length()-3;i++)earlier+=exams.getJSONObject(i).getInt("right")/(double)Math.max(1,exams.getJSONObject(i).getInt("items"));out.append("\nTendencia: últimos tres exámenes ").append(Math.round(recent/3*100)).append(" % · tres anteriores ").append(Math.round(earlier/3*100)).append(" %").append(recent>earlier+.05?" (subiendo)":recent<earlier-.05?" (bajando)":" (sin cambio claro)");}JSONArray review=state.optJSONArray("review");return out.append("\nBloques en repaso: ").append(review==null?0:review.length()).append(" · pasadas de hoy con cargador: ").append(state.optInt("passes")).toString();}
}
